// Ported from the Node app's Sequelize model User (first generated by tools/gen-efcore.mjs).
using System.Text.Json.Nodes;
using System.Text.Json.Serialization;
using SchoolERP.Domain.Common;

namespace SchoolERP.Domain.Entities;

/// <summary>Table <c>users</c>.</summary>
public class User : AuditableEntity, IHasCreatedAt
{
    public int Id { get; set; }
    public string Name { get; set; } = null!;
    public string Email { get; set; } = null!;
    [JsonIgnore] // never sent to a client
    public string PasswordHash { get; set; } = null!;
    public int? RoleId { get; set; }
    public int? StaffId { get; set; }
    public bool MustChangePassword { get; set; } = false;
    public string Role { get; set; } = "admin";
    public DateTime CreatedAt { get; set; }

    [JsonPropertyName("Parent")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Parent? Parent { get; set; }
    [JsonPropertyName("StudentAccount")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public StudentAccount? StudentAccount { get; set; }
    [JsonPropertyName("Role")]
    [JsonIgnore(Condition = JsonIgnoreCondition.WhenWritingNull)]
    public Role? RoleNavigation { get; set; }
    [JsonIgnore]
    public ICollection<UserGroupMember> UserGroupMembers { get; set; } = new List<UserGroupMember>();
    [JsonIgnore]
    public ICollection<PushSubscription> PushSubscriptions { get; set; } = new List<PushSubscription>();
}
